// A built-in rule or tool by its words in the UI language; the person's
// own carry their own words
export const ruleName = (id: string, fallback: string | null) => WORDS[id]?.name[lang()] ?? fallback ?? id
export const ruleAbout = (id: string) => WORDS[id]?.about[lang()] ?? ''
export const toolAbout3d = (id: string) => ABOUT_3D[id]?.[lang()] ?? ''
export const toolStill = (id: string) => STILLS[`../../engine/shotloop/tools/${id}.jpg`] ?? null
